<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\Room; use Carbon\Carbon; use Illuminate\Http\Request;
class RoomAvailabilityController extends Controller { public function __invoke(Request $request){ $data=$request->validate(['property_id'=>['required','integer','exists:properties,id'],'check_in'=>['required','date'],'check_out'=>['required','date','after:check_in'],'room_type_id'=>['nullable','integer','exists:room_types,id']]); $in=Carbon::parse($data['check_in']); $out=Carbon::parse($data['check_out']); $query=Room::with('roomType')->where('property_id',$data['property_id'])->where('is_active',true)->whereNotIn('status',['maintenance','blocked','out_of_order'])->whereDoesntHave('reservationRooms',fn($q)=>$q->whereHas('reservation',fn($r)=>$r->whereIn('status',['pending','confirmed','checked_in']))->where('check_in_at','<',$out)->where('check_out_at','>',$in)); if(!empty($data['room_type_id']))$query->where('room_type_id',$data['room_type_id']); return response()->json(['data'=>$query->orderBy('room_number')->get()]); } }
